"""Contract: the committed SPA bundle must be reproducible by ``npm run build``.

``web-quality`` builds the frontend and then requires the working tree to be
unchanged::

    npm --prefix web run build
    git diff --exit-code -- src/brandly_cli/web/static/

That gate can only ever pass when **every tracked file** under
``src/brandly_cli/web/static/`` is either

* regenerated by the build (``index.html`` and ``assets/index-<hash>.<js|css>``), or
* copied from ``web/public/`` — the only source directory Vite copies wholesale.

RED on main: ``static/README.md`` and ``static/assets/README.md`` were tracked
but had no ``web/public/`` twin, and ``vite.config.ts`` sets
``emptyOutDir: true``, so every build deleted them and the freshness diff could
never be clean (this is the same rule ``tests/test_web_empty_state_preview.py``
pins for ``preview.jpg``).
"""

from __future__ import annotations

import re
import subprocess
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
STATIC_DIR = REPO_ROOT / "src" / "brandly_cli" / "web" / "static"
PUBLIC_DIR = REPO_ROOT / "web" / "public"
INDEX_HTML = STATIC_DIR / "index.html"

STATIC_REL = "src/brandly_cli/web/static"

# Build outputs: never committed by hand, always regenerated by `vite build`.
GENERATED_NAMES = {"index.html"}
GENERATED_RE = re.compile(r"^assets/index-[A-Za-z0-9_-]+\.(js|css)$")


def _tracked_static_files() -> set[str]:
    """Repo-relative paths under static/, from git (build may have deleted some)."""
    proc = subprocess.run(
        ["git", "ls-files", "--", STATIC_REL],
        cwd=REPO_ROOT,
        capture_output=True,
        text=True,
    )
    assert proc.returncode == 0, f"git ls-files failed: {proc.stderr}"
    prefix = f"{STATIC_REL}/"
    return {
        line.strip()[len(prefix) :]
        for line in proc.stdout.splitlines()
        if line.strip().startswith(prefix)
    }


def _public_files() -> set[str]:
    return {
        path.relative_to(PUBLIC_DIR).as_posix()
        for path in PUBLIC_DIR.rglob("*")
        if path.is_file()
    }


def _is_generated(rel: str) -> bool:
    return rel in GENERATED_NAMES or bool(GENERATED_RE.match(rel))


class TestStaticIsReproducible:
    def test_no_tracked_static_file_outside_public(self) -> None:
        """Anything tracked in static/ that the build does not generate must
        come from web/public/, otherwise `emptyOutDir` deletes it forever."""
        public = _public_files()
        orphans = {
            rel for rel in _tracked_static_files() if not _is_generated(rel) and rel not in public
        }
        assert not orphans, (
            "these files are tracked in src/brandly_cli/web/static/ but are neither "
            "build output nor sourced from web/public/ — the bundle-freshness gate "
            f"(`git diff --exit-code`) can never pass: {sorted(orphans)}"
        )

    def test_committed_build_output_is_tracked(self) -> None:
        """Every file Vite would copy in must already be committed in static/."""
        tracked = _tracked_static_files()
        missing = {rel for rel in _public_files() if rel not in tracked}
        assert not missing, (
            "these web/public/ files are not committed in src/brandly_cli/web/static/ — "
            f"run `npm --prefix web run build` and commit the output: {sorted(missing)}"
        )

    def test_index_html_references_tracked_assets(self) -> None:
        """index.html must point at an asset that is actually committed."""
        html = INDEX_HTML.read_text(encoding="utf-8")
        referenced = set(re.findall(r"/static/(assets/index-[A-Za-z0-9_-]+\.(?:js|css))", html))
        assert referenced, "index.html references no hashed bundle under /static/assets/"
        tracked = _tracked_static_files()
        for rel in sorted(referenced):
            assert rel in tracked, (
                f"index.html references /static/{rel}, which is not committed in "
                "src/brandly_cli/web/static/ — rebuild and commit the bundle"
            )
        assert any(rel.endswith(".js") for rel in referenced), "index.html must load a JS bundle"
